/**
 * @distilled.cloud/convex -- Convex SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from Convex's OpenAPI specs. Everything
 * else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Convex from "@distilled.cloud/convex";
 *
 * const program = Effect.gen(function* () {
 *   const { id, deploymentUrl } = yield* Convex.management.createProject({
 *     teamId: 12345,
 *     projectName: "my-app",
 *     deploymentType: "prod",
 *   });
 *   return { id, deploymentUrl };
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Convex.CredentialsFromEnv,
 *   Convex.ConvexProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export * as Retry from "./retry.ts";
export { paginateCursor } from "./pagination.ts";
export {
  ConvexProtocol,
  ConvexDeploymentProtocol,
  ConvexFunctionsProtocol,
  type ConvexOpError,
  type ConvexOpContext,
} from "./protocol.ts";
export * from "./services/index.ts";
